import asyncio
import json
import os
import base64
import tempfile
import pyperclip
import tkinter as tk
from tkinter import ttk, messagebox
import threading
from playwright.async_api import async_playwright
from cryptography.fernet import Fernet
import sys

# ---------------------------------------------------------------------------
# App icon - plumbob icon baked in as base64 so there's no external file to
# bundle or lose track of. Generated once via:
#   python -c "import base64; print(base64.b64encode(open('file_name.png','rb').read()).decode())"
# ---------------------------------------------------------------------------
ICON_B64 = ""

# ---------------------------------------------------------------------------
# Path resolution - in case files as frozen
# ---------------------------------------------------------------------------
def resource_path(relative_path):
    if getattr(sys, 'frozen', False):
        return os.path.join(sys._MEIPASS, relative_path)
    return os.path.join(os.path.dirname(__file__), relative_path)
 
# Tell Playwright where to find its bundled Chromium when running as an .exe
if getattr(sys, 'frozen', False):
    os.environ["PLAYWRIGHT_BROWSERS_PATH"] = os.path.join(sys._MEIPASS, "ms-playwright")
 
# ---------------------------------------------------------------------------
# Credential storage paths - kept in the user's home directory so they
# survive app updates and are never accidentally committed to a repo.
# ---------------------------------------------------------------------------
SAVE_FILE = os.path.join(os.path.expanduser("~"), ".remid_config.json")
KEY_FILE  = os.path.join(os.path.expanduser("~"), ".remid_key")
 
 
# -- Encryption helpers ------------------------------------------------------
 
def get_or_create_key():
    """Load the Fernet key from disk, or generate a new one on first run."""
    if os.path.exists(KEY_FILE):
        with open(KEY_FILE, "rb") as f:
            return f.read()
    key = Fernet.generate_key()
    with open(KEY_FILE, "wb") as f:
        f.write(key)
    return key
 
def encrypt(text):
    """Encrypt a plaintext string and return a base64-encoded ciphertext."""
    f = Fernet(get_or_create_key())
    return f.encrypt(text.encode()).decode()
 
def decrypt(text):
    """Decrypt a base64-encoded ciphertext and return the original string."""
    f = Fernet(get_or_create_key())
    return f.decrypt(text.encode()).decode()
 
 
# -- Credential persistence --------------------------------------------------
 
def load_credentials():
    """
    Read saved credentials from disk and decrypt them.
    Returns empty strings if the file doesn't exist or decryption fails
    (e.g. the key file was deleted separately).
    """
    if os.path.exists(SAVE_FILE):
        with open(SAVE_FILE, "r") as f:
            data = json.load(f)
        try:
            return {
                "email":    decrypt(data.get("email", "")),
                "password": decrypt(data.get("password", ""))
            }
        except Exception:
            # Key mismatch or corrupted file — start fresh rather than crash
            return {"email": "", "password": ""}
    return {"email": "", "password": ""}
 
def save_credentials(email, password):
    """Encrypt and persist credentials to disk before each login attempt."""
    with open(SAVE_FILE, "w") as f:
        json.dump({"email": encrypt(email), "password": encrypt(password)}, f)
 
 
# ---------------------------------------------------------------------------
# Core logic - automates the EA login flow and extracts the remid cookie.
# ---------------------------------------------------------------------------
 
async def get_remid(email, password, status_callback):
    """
    Launch a Chromium browser (visible so EA doesn't flag it as a bot),
    log into the EA account, then scrape the remid cookie from
    accounts.ea.com/connect.
 
    status_callback(str) is called at each step so the UI can display
    live progress without blocking the main thread.
    """
    async with async_playwright() as p:
        browser = await p.chromium.launch(
            headless=False,
            args=["--disable-blink-features=AutomationControlled"]
        )
        context = await browser.new_context(
            # Spoof EA's login checks 
            user_agent=(
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/124.0.0.0 Safari/537.36"
            )
        )
        page = await context.new_page()
 
        # Remove the webdriver flag so EA doesn't detect automation
        await page.add_init_script("""
            Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
        """)
 
        status_callback("Opening EA login page...")
        await page.goto("https://www.ea.com/login", wait_until="domcontentloaded")
 
        status_callback("Waiting for email field...")
        await page.wait_for_selector('input[id="email"]', timeout=20000)
        await asyncio.sleep(1.5)
 
        status_callback("Typing email...")
        await page.click('input[id="email"]')
        await page.type('input[id="email"]', email, delay=80)
        await asyncio.sleep(1)
 
        status_callback("Submitting email...")
        await page.keyboard.press("Enter")
        await asyncio.sleep(3)
 
        # The password field is sometimes hidden by EA's step-by-step flow;
        # wait for it to become visible before interacting with it.
        status_callback("Waiting for password field...")
        try:
            await page.wait_for_function("""
                () => {
                    const pwd = document.getElementById('password');
                    return pwd && pwd.offsetParent !== null;
                }
            """, timeout=15000)
        except Exception:
            pass  # Field might already be visible — continue anyway
 
        await asyncio.sleep(1)
 
        # Force the field visible just in case CSS is hiding it
        await page.evaluate("""
            const pwd = document.getElementById('password');
            if (pwd) {
                pwd.style.display = 'block';
                pwd.style.visibility = 'visible';
            }
        """)
 
        status_callback("Typing password...")
        await page.click('input[id="password"]')
        await page.type('input[id="password"]', password, delay=80)
        await asyncio.sleep(1)
 
        status_callback("Logging in...")
        await page.keyboard.press("Enter")
 
        # EA sometimes shows a "confirm your email" interstitial - dismiss it
        # automatically and wait until we leave the signin subdomain.
        status_callback("Handling interstitial pages...")
        for _ in range(8):
            await asyncio.sleep(2)
            current_url = page.url
            remind_later = page.locator(
                'a:has-text("Remind me later"), button:has-text("Remind me later")'
            )
            if await remind_later.count() > 0:
                status_callback("Dismissing email confirmation...")
                await remind_later.first.click()
                continue
            if "signin.ea.com" not in current_url:
                break  # Successfully past the login wall
 
        # Navigate to the accounts page where the remid cookie is set
        await asyncio.sleep(2)
        status_callback("Grabbing remid cookie...")
        await page.goto("https://accounts.ea.com/connect", wait_until="domcontentloaded")
        await asyncio.sleep(2)
 
        all_cookies = await context.cookies()
        remid = next((c for c in all_cookies if c["name"] == "remid"), None)
        await browser.close()
 
        return remid["value"] if remid else None
 
 
# ---------------------------------------------------------------------------
# GUI
# ---------------------------------------------------------------------------
 
class App(tk.Tk):
    def __init__(self):
        super().__init__()
 
        # Set the window/taskbar icon from the embedded base64 PNG.
        # We write it to a temp file because tkinter's PhotoImage needs
        # a file path since it can't load from bytes directly.
        try:
            icon_data = base64.b64decode(ICON_B64)
            tmp = tempfile.NamedTemporaryFile(delete=False, suffix=".png")
            tmp.write(icon_data)
            tmp.close()
            img = tk.PhotoImage(file=tmp.name)
            self._icon = img  # keep a reference - GC will drop it otherwise
            self.tk.call('wm', 'iconphoto', self._w, img)
        except Exception:
            pass  # Non-fatal — app still works without the icon
 
        self.title("Sims 4 Remid Grabber")
        self.resizable(False, False)
        self.configure(bg="#1a1a2e")
        self._center()
        self._build_ui()
        self._load()
 
    def _center(self):
        """Position the window in the middle of the screen on launch."""
        self.update_idletasks()
        w, h = 420, 360
        x = (self.winfo_screenwidth()  - w) // 2
        y = (self.winfo_screenheight() - h) // 2
        self.geometry(f"{w}x{h}+{x}+{y}")
 
    def _build_ui(self):
        """Build all widgets. Called once from __init__."""
        style = ttk.Style(self)
        style.theme_use("clam")
        style.configure("TEntry",
            fieldbackground="#16213e", foreground="white",
            bordercolor="#0f3460", relief="flat", padding=6)
        style.configure("Accent.TButton",
            background="#0f3460", foreground="white",
            font=("Segoe UI", 10, "bold"), borderwidth=0, padding=8)
        style.map("Accent.TButton", background=[("active", "#1a4a8a")])
 
        # Header
        tk.Label(self, text="🎮 Sims 4 Remid Grabber",
                 bg="#1a1a2e", fg="white",
                 font=("Segoe UI", 14, "bold")).pack(pady=(20, 4))
        tk.Label(self, text="Automatically grabs your remid cookie from EA",
                 bg="#1a1a2e", fg="#aaaaaa",
                 font=("Segoe UI", 9)).pack(pady=(0, 20))
 
        frame = tk.Frame(self, bg="#1a1a2e")
        frame.pack(padx=30, fill="x")
 
        # Email field
        tk.Label(frame, text="EA Email",
                 bg="#1a1a2e", fg="#cccccc",
                 font=("Segoe UI", 9)).pack(anchor="w")
        self.email_var = tk.StringVar()
        ttk.Entry(frame, textvariable=self.email_var, width=40).pack(fill="x", pady=(2, 10))
 
        # Password field + eye toggle
        tk.Label(frame, text="EA Password",
                 bg="#1a1a2e", fg="#cccccc",
                 font=("Segoe UI", 9)).pack(anchor="w")
 
        pass_row = tk.Frame(frame, bg="#1a1a2e")
        pass_row.pack(fill="x", pady=(2, 10))
 
        self.pass_var   = tk.StringVar()
        self.pass_entry = ttk.Entry(pass_row, textvariable=self.pass_var,
                                    show="●", width=36)
        self.pass_entry.pack(side="left", fill="x", expand=True)
 
        self.show_pass = False
        self.eye_btn = tk.Button(
            pass_row, text="👁",
            bg="#16213e", fg="white",
            relief="flat", bd=0, cursor="hand2",
            font=("Segoe UI", 11),
            activebackground="#1a2a4e", activeforeground="white",
            command=self._toggle_password
        )
        self.eye_btn.pack(side="left", padx=(4, 0))
 
        # Status label - updated live during the login flow
        self.status_var = tk.StringVar(value="Ready.")
        tk.Label(self, textvariable=self.status_var,
                 bg="#1a1a2e", fg="#4fc3f7",
                 font=("Segoe UI", 9), wraplength=380).pack(pady=(6, 10))
 
        # Action buttons
        btn_frame = tk.Frame(self, bg="#1a1a2e")
        btn_frame.pack(pady=(0, 20))
        ttk.Button(btn_frame, text="Grab Remid Cookie",
                   style="Accent.TButton",
                   command=self._run).pack(side="left", padx=6)
        ttk.Button(btn_frame, text="Clear Saved",
                   style="Accent.TButton",
                   command=self._clear).pack(side="left", padx=6)
 
    def _toggle_password(self):
        """Switch the password field between masked and plaintext."""
        self.show_pass = not self.show_pass
        self.pass_entry.config(show="" if self.show_pass else "●")
 
    def _load(self):
        """Pre-fill fields with any previously saved credentials."""
        creds = load_credentials()
        self.email_var.set(creds.get("email", ""))
        self.pass_var.set(creds.get("password", ""))
 
    def _clear(self):
        """Wipe the form and delete both the credentials and key files."""
        self.email_var.set("")
        self.pass_var.set("")
        for path in [SAVE_FILE, KEY_FILE]:
            if os.path.exists(path):
                os.remove(path)
        self.status_var.set("Credentials cleared.")
 
    def _run(self):
        """Validate inputs, save credentials, then kick off the async grab."""
        email    = self.email_var.get().strip()
        password = self.pass_var.get().strip()
 
        if not email or not password:
            messagebox.showerror("Missing info", "Please enter your email and password.")
            return
 
        save_credentials(email, password)
        self.status_var.set("Starting...")
 
        # Run on a background thread so the UI stays responsive
        threading.Thread(
            target=self._run_async,
            args=(email, password),
            daemon=True
        ).start()
 
    def _run_async(self, email, password):
        """
        Create a fresh event loop on the worker thread, run the Playwright
        coroutine, then surface the result back to the main thread.
        """
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        try:
            result = loop.run_until_complete(
                get_remid(email, password, self._set_status)
            )
            if result:
                pyperclip.copy(result)
                with open("remid.txt", "w") as f:
                    f.write(result)
                self._set_status("Copied to clipboard! Paste into Sims 4 popup.")
            else:
                self._set_status("remid not found. Try again.")
        except Exception as e:
            self._set_status(f"Error: {str(e)}")
        finally:
            loop.close()
 
    def _set_status(self, msg):
        """Thread-safe status update — schedules the label change on the main loop."""
        self.after(0, lambda: self.status_var.set(msg))
 
 
# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
 
if __name__ == "__main__":
    app = App()
    app.mainloop()
